INSERT INTO verses (translation_id, book_id, chapter, verse, text, words_of_jesus) VALUES
('web','GEN',1,1,'In the beginning, God created the heavens and the earth.',NULL),
('web','GEN',1,2,'The earth was formless and empty. Darkness was on the surface of the deep and God’s Spirit was hovering over the surface of the waters.',NULL),
('web','GEN',1,3,'God said, “Let there be light,” and there was light.',NULL),
('web','GEN',1,4,'God saw the light, and saw that it was good. God divided the light from the darkness.',NULL),
('web','GEN',1,5,'God called the light “day”, and the darkness he called “night”. There was evening and there was morning, the first day.',NULL),
('web','GEN',1,6,'God said, “Let there be an expanse in the middle of the waters, and let it divide the waters from the waters.”',NULL),
('web','GEN',1,7,'God made the expanse, and divided the waters which were under the expanse from the waters which were above the expanse; and it was so.',NULL),
('web','GEN',1,8,'God called the expanse “sky”. There was evening and there was morning, a second day.',NULL),
('web','GEN',1,9,'God said, “Let the waters under the sky be gathered together to one place, and let the dry land appear;” and it was so.',NULL),
('web','GEN',1,10,'God called the dry land “earth”, and the gathering together of the waters he called “seas”. God saw that it was good.',NULL),
('web','GEN',1,11,'God said, “Let the earth yield grass, herbs yielding seeds, and fruit trees bearing fruit after their kind, with their seeds in it, on the earth;” and it was so.',NULL),
('web','GEN',1,12,'The earth yielded grass, herbs yielding seed after their kind, and trees bearing fruit, with their seeds in it, after their kind; and God saw that it was good.',NULL),
('web','GEN',1,13,'There was evening and there was morning, a third day.',NULL),
('web','GEN',1,14,'God said, “Let there be lights in the expanse of the sky to divide the day from the night; and let them be for signs to mark seasons, days, and years;',NULL),
('web','GEN',1,15,'and let them be for lights in the expanse of the sky to give light on the earth;” and it was so.',NULL),
('web','GEN',1,16,'God made the two great lights: the greater light to rule the day, and the lesser light to rule the night. He also made the stars.',NULL),
('web','GEN',1,17,'God set them in the expanse of the sky to give light to the earth,',NULL),
('web','GEN',1,18,'and to rule over the day and over the night, and to divide the light from the darkness. God saw that it was good.',NULL),
('web','GEN',1,19,'There was evening and there was morning, a fourth day.',NULL),
('web','GEN',1,20,'God said, “Let the waters abound with living creatures, and let birds fly above the earth in the open expanse of the sky.”',NULL),
('web','GEN',1,21,'God created the large sea creatures and every living creature that moves, with which the waters swarmed, after their kind, and every winged bird after its kind. God saw that it was good.',NULL),
('web','GEN',1,22,'God blessed them, saying, “Be fruitful, and multiply, and fill the waters in the seas, and let birds multiply on the earth.”',NULL),
('web','GEN',1,23,'There was evening and there was morning, a fifth day.',NULL),
('web','GEN',1,24,'God said, “Let the earth produce living creatures after their kind, livestock, creeping things, and animals of the earth after their kind;” and it was so.',NULL),
('web','GEN',1,25,'God made the animals of the earth after their kind, and the livestock after their kind, and everything that creeps on the ground after its kind. God saw that it was good.',NULL),
('web','GEN',1,26,'God said, “Let’s make man in our image, after our likeness. Let them have dominion over the fish of the sea, and over the birds of the sky, and over the livestock, and over all the earth, and over every creeping thing that creeps on the earth.”',NULL),
('web','GEN',1,27,'God created man in his own image. In God’s image he created him; male and female he created them.',NULL),
('web','GEN',1,28,'God blessed them. God said to them, “Be fruitful, multiply, fill the earth, and subdue it. Have dominion over the fish of the sea, over the birds of the sky, and over every living thing that moves on the earth.”',NULL),
('web','GEN',1,29,'God said, “Behold, I have given you every herb yielding seed, which is on the surface of all the earth, and every tree, which bears fruit yielding seed. It will be your food.',NULL),
('web','GEN',1,30,'To every animal of the earth, and to every bird of the sky, and to everything that creeps on the earth, in which there is life, I have given every green herb for food;” and it was so.',NULL),
('web','GEN',1,31,'God saw everything that he had made, and, behold, it was very good. There was evening and there was morning, a sixth day.',NULL),
('web','PSA',23,1,'The LORD is my shepherd; I shall lack nothing.',NULL),
('web','PSA',23,2,'He makes me lie down in green pastures. He leads me beside still waters.',NULL),
('web','PSA',23,3,'He restores my soul. He guides me in the paths of righteousness for his name’s sake.',NULL),
('web','PSA',23,4,'Even though I walk through the valley of the shadow of death, I will fear no evil, for you are with me. Your rod and your staff, they comfort me.',NULL),
('web','PSA',23,5,'You prepare a table before me in the presence of my enemies. You anoint my head with oil. My cup runs over.',NULL),
('web','PSA',23,6,'Surely goodness and loving kindness shall follow me all the days of my life, and I will dwell in the LORD’s house forever.',NULL),
('web','PSA',117,1,'Praise the LORD, all you nations! Extol him, all you peoples!',NULL),
('web','PSA',117,2,'For his loving kindness is great toward us. The LORD’s faithfulness endures forever. Praise the LORD!',NULL),
('web','MAT',11,1,'When Jesus had finished directing his twelve disciples, he departed from there to teach and preach in their cities.',NULL),
('web','MAT',11,2,'Now when John heard in the prison the works of Christ, he sent two of his disciples',NULL),
('web','MAT',11,3,'and said to him, “Are you he who comes, or should we look for another?”',NULL),
('web','MAT',11,4,'Jesus answered them, “Go and tell John the things which you hear and see:','[[21,52]]'),
('web','MAT',11,5,'the blind receive their sight, the lame walk, the lepers are cleansed, the deaf hear, the dead are raised up, and the poor have good news preached to them.','[[0,155]]'),
('web','MAT',11,6,'Blessed is he who finds no occasion for stumbling in me.”','[[0,57]]'),
('web','MAT',11,7,'As these went their way, Jesus began to say to the multitudes concerning John, “What did you go out into the wilderness to see? A reed shaken by the wind?','[[79,75]]'),
('web','MAT',11,8,'But what did you go out to see? A man in soft clothing? Behold, those who wear soft clothing are in kings’ houses.','[[0,114]]'),
('web','MAT',11,9,'But why did you go out? To see a prophet? Yes, I tell you, and much more than a prophet.','[[0,88]]'),
('web','MAT',11,10,'For this is he, of whom it is written, ‘Behold, I send my messenger before your face, who will prepare your way before you.’','[[0,124]]'),
('web','MAT',11,11,'Most certainly I tell you, among those who are born of women there has not arisen anyone greater than John the Baptizer; yet he who is least in the Kingdom of Heaven is greater than he.','[[0,185]]'),
('web','MAT',11,12,'From the days of John the Baptizer until now, the Kingdom of Heaven suffers violence, and the violent take it by force.','[[0,119]]'),
('web','MAT',11,13,'For all the prophets and the law prophesied until John.','[[0,55]]'),
('web','MAT',11,14,'If you are willing to receive it, this is Elijah, who is to come.','[[0,65]]'),
('web','MAT',11,15,'He who has ears to hear, let him hear.','[[0,38]]'),
('web','MAT',11,16,'“But to what shall I compare this generation? It is like children sitting in the marketplaces, who call to their companions','[[0,123]]'),
('web','MAT',11,17,'and say, ‘We played the flute for you, and you didn’t dance. We mourned for you, and you didn’t lament.’','[[0,104]]'),
('web','MAT',11,18,'For John came neither eating nor drinking, and they say, ‘He has a demon.’','[[0,74]]'),
('web','MAT',11,19,'The Son of Man came eating and drinking, and they say, ‘Behold, a gluttonous man and a drunkard, a friend of tax collectors and sinners!’ But wisdom is justified by her children.”','[[0,179]]'),
('web','MAT',11,20,'Then he began to denounce the cities in which most of his mighty works had been done, because they didn’t repent.',NULL),
('web','MAT',11,21,'“Woe to you, Chorazin! Woe to you, Bethsaida! For if the mighty works had been done in Tyre and Sidon which were done in you, they would have repented long ago in sackcloth and ashes.','[[0,183]]'),
('web','MAT',11,22,'But I tell you, it will be more tolerable for Tyre and Sidon on the day of judgment than for you.','[[0,97]]'),
('web','MAT',11,23,'You, Capernaum, who are exalted to heaven, you will go down to Hades. For if the mighty works had been done in Sodom which were done in you, it would have remained until today.','[[0,176]]'),
('web','MAT',11,24,'But I tell you that it will be more tolerable for the land of Sodom on the day of judgment, than for you.”','[[0,106]]'),
('web','MAT',11,25,'At that time, Jesus answered, “I thank you, Father, Lord of heaven and earth, that you hid these things from the wise and understanding, and revealed them to infants.','[[30,136]]'),
('web','MAT',11,26,'Yes, Father, for so it was well-pleasing in your sight.','[[0,55]]'),
('web','MAT',11,27,'All things have been delivered to me by my Father. No one knows the Son, except the Father; neither does anyone know the Father, except the Son and he to whom the Son desires to reveal him.','[[0,189]]'),
('web','MAT',11,28,'“Come to me, all you who labor and are heavily burdened, and I will give you rest.','[[0,82]]'),
('web','MAT',11,29,'Take my yoke upon you and learn from me, for I am gentle and humble in heart; and you will find rest for your souls.','[[0,116]]'),
('web','MAT',11,30,'For my yoke is easy, and my burden is light.”','[[0,45]]'),
('web','MAT',17,1,'After six days, Jesus took with him Peter, James, and John his brother, and brought them up into a high mountain by themselves.',NULL),
('web','MAT',17,2,'He was changed before them. His face shone like the sun, and his garments became as white as the light.',NULL),
('web','MAT',17,3,'Behold, Moses and Elijah appeared to them talking with him.',NULL),
('web','MAT',17,4,'Peter answered and said to Jesus, “Lord, it is good for us to be here. If you want, let’s make three tents here: one for you, one for Moses, and one for Elijah.”',NULL),
('web','MAT',17,5,'While he was still speaking, behold, a bright cloud overshadowed them. Behold, a voice came out of the cloud, saying, “This is my beloved Son, in whom I am well pleased. Listen to him.”',NULL),
('web','MAT',17,6,'When the disciples heard it, they fell on their faces, and were very afraid.',NULL),
('web','MAT',17,7,'Jesus came and touched them and said, “Get up, and don’t be afraid.”','[[38,30]]'),
('web','MAT',17,8,'Lifting up their eyes, they saw no one, except Jesus alone.',NULL),
('web','MAT',17,9,'As they were coming down from the mountain, Jesus commanded them, saying, “Don’t tell anyone what you saw, until the Son of Man has risen from the dead.”','[[74,79]]'),
('web','MAT',17,10,'His disciples asked him, saying, “Then why do the scribes say that Elijah must come first?”',NULL),
('web','MAT',17,11,'Jesus answered them, “Elijah indeed comes first, and will restore all things;','[[21,56]]'),
('web','MAT',17,12,'but I tell you that Elijah has come already, and they didn’t recognize him, but did to him whatever they wanted to. Even so the Son of Man will also suffer by them.”','[[0,165]]'),
('web','MAT',17,13,'Then the disciples understood that he spoke to them of John the Baptizer.',NULL),
('web','MAT',17,14,'When they came to the multitude, a man came to him, kneeling down to him and saying,',NULL),
('web','MAT',17,15,'“Lord, have mercy on my son, for he is epileptic and suffers grievously; for he often falls into the fire, and often into the water.',NULL),
('web','MAT',17,16,'So I brought him to your disciples, and they could not cure him.”',NULL),
('web','MAT',17,17,'Jesus answered, “Faithless and perverse generation! How long will I be with you? How long will I bear with you? Bring him here to me.”','[[16,118]]'),
('web','MAT',17,18,'Jesus rebuked the demon, and it went out of him, and the boy was cured from that hour.',NULL),
('web','MAT',17,19,'Then the disciples came to Jesus privately, and said, “Why weren’t we able to cast it out?”',NULL),
('web','MAT',17,20,'He said to them, “Because of your unbelief. For most certainly I tell you, if you have faith as a grain of mustard seed, you will tell this mountain, ‘Move from here to there,’ and it will move; and nothing will be impossible for you.','[[17,217]]'),
('web','MAT',17,21,'But this kind doesn’t go out except by prayer and fasting.”','[[0,59]]'),
('web','MAT',17,22,'While they were staying in Galilee, Jesus said to them, “The Son of Man is about to be delivered up into the hands of men,','[[56,66]]'),
('web','MAT',17,23,'and they will kill him, and the third day he will be raised up.” They were exceedingly sorry.','[[0,64]]'),
('web','MAT',17,24,'When they had come to Capernaum, those who collected the didrachma coins came to Peter, and said, “Doesn’t your teacher pay the didrachma?”',NULL),
('web','MAT',17,25,'He said, “Yes.” When he came into the house, Jesus anticipated him, saying, “What do you think, Simon? From whom do the kings of the earth receive toll or tribute? From their children, or from strangers?”','[[76,128]]'),
('web','MAT',17,26,'Peter said to him, “From strangers.” Jesus said to him, “Therefore the children are exempt.','[[56,35]]'),
('web','MAT',17,27,'But, lest we cause them to stumble, go to the sea, cast a hook, and take up the first fish that comes up. When you have opened its mouth, you will find a stater coin. Take that, and give it to them for me and you.”','[[0,214]]'),
('web','JHN',3,1,'Now there was a man of the Pharisees named Nicodemus, a ruler of the Jews.',NULL),
('web','JHN',3,2,'He came to Jesus by night and said to him, “Rabbi, we know that you are a teacher who has come from God, for no one can do these signs that you do, unless God is with him.”',NULL),
('web','JHN',3,3,'Jesus answered him, “Most certainly I tell you, unless one is born anew, he can’t see God’s Kingdom.”','[[20,81]]'),
('web','JHN',3,4,'Nicodemus said to him, “How can a man be born when he is old? Can he enter a second time into his mother’s womb and be born?”',NULL),
('web','JHN',3,5,'Jesus answered, “Most certainly I tell you, unless one is born of water and Spirit, he can’t enter into God’s Kingdom.','[[16,102]]'),
('web','JHN',3,6,'That which is born of the flesh is flesh. That which is born of the Spirit is spirit.','[[0,85]]'),
('web','JHN',3,7,'Don’t marvel that I said to you, ‘You must all be born anew.’','[[0,61]]'),
('web','JHN',3,8,'The wind blows where it wants to, and you hear its sound, but don’t know where it comes from and where it is going. So is everyone who is born of the Spirit.”','[[0,158]]'),
('web','JHN',3,9,'Nicodemus answered him, “How can these things be?”',NULL),
('web','JHN',3,10,'Jesus answered him, “Are you the teacher of Israel, and don’t understand these things?','[[20,66]]'),
('web','JHN',3,11,'Most certainly I tell you, we speak that which we know and testify of that which we have seen, and you don’t receive our witness.','[[0,129]]'),
('web','JHN',3,12,'If I told you earthly things and you don’t believe, how will you believe if I tell you heavenly things?','[[0,103]]'),
('web','JHN',3,13,'No one has ascended into heaven but he who descended out of heaven, the Son of Man, who is in heaven.','[[0,101]]'),
('web','JHN',3,14,'As Moses lifted up the serpent in the wilderness, even so must the Son of Man be lifted up,','[[0,91]]'),
('web','JHN',3,15,'that whoever believes in him should not perish, but have eternal life.','[[0,70]]'),
('web','JHN',3,16,'For God so loved the world, that he gave his only born Son, that whoever believes in him should not perish, but have eternal life.','[[0,130]]'),
('web','JHN',3,17,'For God didn’t send his Son into the world to judge the world, but that the world should be saved through him.','[[0,110]]'),
('web','JHN',3,18,'He who believes in him is not judged. He who doesn’t believe has been judged already, because he has not believed in the name of the only born Son of God.','[[0,154]]'),
('web','JHN',3,19,'This is the judgment, that the light has come into the world, and men loved the darkness rather than the light, for their works were evil.','[[0,138]]'),
('web','JHN',3,20,'For everyone who does evil hates the light and doesn’t come to the light, lest his works would be exposed.','[[0,106]]'),
('web','JHN',3,21,'But he who does the truth comes to the light, that his works may be revealed, that they have been done in God.”','[[0,111]]'),
('web','JHN',3,22,'After these things, Jesus came with his disciples into the land of Judea. He stayed there with them and baptized.',NULL),
('web','JHN',3,23,'John also was baptizing in Enon near Salim, because there was much water there. They came and were baptized;',NULL),
('web','JHN',3,24,'for John was not yet thrown into prison.',NULL),
('web','JHN',3,25,'Therefore a dispute arose on the part of John’s disciples with some Jews about purification.',NULL),
('web','JHN',3,26,'They came to John and said to him, “Rabbi, he who was with you beyond the Jordan, to whom you have testified, behold, he baptizes, and everyone is coming to him.”',NULL),
('web','JHN',3,27,'John answered, “A man can receive nothing unless it has been given him from heaven.',NULL),
('web','JHN',3,28,'You yourselves testify that I said, ‘I am not the Christ,’ but, ‘I have been sent before him.’',NULL),
('web','JHN',3,29,'He who has the bride is the bridegroom; but the friend of the bridegroom, who stands and hears him, rejoices greatly because of the bridegroom’s voice. Therefore my joy is made full.',NULL),
('web','JHN',3,30,'He must increase, but I must decrease.',NULL),
('web','JHN',3,31,'“He who comes from above is above all. He who is from the earth belongs to the earth and speaks of the earth. He who comes from heaven is above all.',NULL),
('web','JHN',3,32,'What he has seen and heard, of that he testifies; and no one receives his witness.',NULL),
('web','JHN',3,33,'He who has received his witness has set his seal to this, that God is true.',NULL),
('web','JHN',3,34,'For he whom God has sent speaks the words of God; for God gives the Spirit without measure.',NULL),
('web','JHN',3,35,'The Father loves the Son, and has given all things into his hand.',NULL),
('web','JHN',3,36,'One who believes in the Son has eternal life, but one who disobeys the Son won’t see life, but the wrath of God remains on him.”',NULL),
('web','3JN',1,1,'The elder to Gaius the beloved, whom I love in truth.',NULL),
('web','3JN',1,2,'Beloved, I pray that you may prosper in all things and be healthy, even as your soul prospers.',NULL),
('web','3JN',1,3,'For I rejoiced greatly when brothers came and testified about your truth, even as you walk in truth.',NULL),
('web','3JN',1,4,'I have no greater joy than this: to hear about my children walking in truth.',NULL),
('web','3JN',1,5,'Beloved, you do a faithful work in whatever you accomplish for those who are brothers and strangers.',NULL),
('web','3JN',1,6,'They have testified about your love before the assembly. You will do well to send them forward on their journey in a way worthy of God,',NULL),
('web','3JN',1,7,'because for the sake of the Name they went out, taking nothing from the Gentiles.',NULL),
('web','3JN',1,8,'We therefore ought to receive such, that we may be fellow workers for the truth.',NULL),
('web','3JN',1,9,'I wrote to the assembly, but Diotrephes, who loves to be first among them, doesn’t accept what we say.',NULL),
('web','3JN',1,10,'Therefore, if I come, I will call attention to his deeds which he does, unjustly accusing us with wicked words. Not content with this, he doesn’t receive the brothers himself, and those who would, he forbids and throws out of the assembly.',NULL),
('web','3JN',1,11,'Beloved, don’t imitate that which is evil, but that which is good. He who does good is of God. He who does evil hasn’t seen God.',NULL),
('web','3JN',1,12,'Demetrius has the testimony of all, and of the truth itself; yes, we also testify, and you know that our testimony is true.',NULL),
('web','3JN',1,13,'I had many things to write to you, but I am unwilling to write to you with ink and pen;',NULL),
('web','3JN',1,14,'but I hope to see you soon. Then we will speak face to face. Peace be to you. The friends greet you. Greet the friends by name.',NULL),
('web','REV',12,1,'A great sign was seen in heaven: a woman clothed with the sun, and the moon under her feet, and on her head a crown of twelve stars.',NULL),
('web','REV',12,2,'She was with child. She cried out in pain, laboring to give birth.',NULL),
('web','REV',12,3,'Another sign was seen in heaven. Behold, a great red dragon, having seven heads and ten horns, and on his heads seven crowns.',NULL),
('web','REV',12,4,'His tail drew one third of the stars of the sky, and threw them to the earth. The dragon stood before the woman who was about to give birth, so that when she gave birth he might devour her child.',NULL),
('web','REV',12,5,'She gave birth to a son, a male child, who is to rule all the nations with a rod of iron. Her child was caught up to God and to his throne.',NULL),
('web','REV',12,6,'The woman fled into the wilderness, where she has a place prepared by God, that there they may nourish her one thousand two hundred sixty days.',NULL),
('web','REV',12,7,'There was war in the sky. Michael and his angels made war on the dragon. The dragon and his angels made war.',NULL),
('web','REV',12,8,'They didn’t prevail. No place was found for them any more in heaven.',NULL),
('web','REV',12,9,'The great dragon was thrown down, the old serpent, he who is called the devil and Satan, the deceiver of the whole world. He was thrown down to the earth, and his angels were thrown down with him.',NULL),
('web','REV',12,10,'I heard a loud voice in heaven, saying, “Now the salvation, the power, and the Kingdom of our God, and the authority of his Christ has come; for the accuser of our brothers has been thrown down, who accuses them before our God day and night.',NULL),
('web','REV',12,11,'They overcame him because of the Lamb’s blood, and because of the word of their testimony. They didn’t love their life, even to death.',NULL),
('web','REV',12,12,'Therefore rejoice, heavens, and you who dwell in them. Woe to the earth and to the sea, because the devil has gone down to you, having great wrath, knowing that he has but a short time.”',NULL),
('web','REV',12,13,'When the dragon saw that he was thrown down to the earth, he persecuted the woman who gave birth to the male child.',NULL),
('web','REV',12,14,'Two wings of the great eagle were given to the woman, that she might fly into the wilderness to her place, so that she might be nourished for a time, times, and half a time, from the face of the serpent.',NULL),
('web','REV',12,15,'The serpent spewed water out of his mouth after the woman like a river, that he might cause her to be carried away by the stream.',NULL),
('web','REV',12,16,'The earth helped the woman, and the earth opened its mouth and swallowed up the river which the dragon spewed out of his mouth.',NULL),
('web','REV',12,17,'The dragon grew angry with the woman, and went away to make war with the rest of her offspring, who keep God’s commandments and hold Jesus’ testimony.',NULL);
INSERT INTO chapter_titles (translation_id, book_id, chapter, text) VALUES
('web','PSA',23,'A Psalm by David.');
INSERT INTO verses_fts (verses_fts) VALUES ('rebuild');
